//! The Unicode 18.0 conformance tests for grapheme clusters, words and line breaks. The data
//! files are generated by `cargo xtask unicode-gen` and keep only the test lines.

use duydas_text::{Strictness, graphemes, line_breaks, words};

/// Each test case: the text and the byte offsets of its boundaries after the start.
fn cases(data: &str) -> Vec<(String, Vec<usize>)> {
    let mut cases = Vec::new();
    for line in data.lines().filter(|l| !l.starts_with('#')) {
        let mut text = String::new();
        let mut boundaries = Vec::new();
        for token in line.split_whitespace() {
            match token {
                "÷" if !text.is_empty() => boundaries.push(text.len()),
                "÷" | "×" => {}
                hex => {
                    let cp = u32::from_str_radix(hex, 16).expect("hex code point");
                    text.push(char::from_u32(cp).expect("test data has no surrogates"));
                }
            }
        }
        cases.push((text, boundaries));
    }
    cases
}

fn ends<'a>(segments: impl Iterator<Item = &'a str>) -> Vec<usize> {
    let mut end = 0;
    segments
        .map(|s| {
            end += s.len();
            end
        })
        .collect()
}

fn check(name: &str, data: &str, actual: impl Fn(&str) -> Vec<usize>, expected_cases: usize) {
    let cases = cases(data);
    assert_eq!(cases.len(), expected_cases, "{name}: number of cases");
    let failures: Vec<String> = cases
        .iter()
        .filter(|(text, expected)| actual(text) != *expected)
        .map(|(text, expected)| {
            let cps: Vec<String> = text.chars().map(|c| format!("{:04X}", c as u32)).collect();
            format!(
                "[{}] expected {expected:?}, got {:?}",
                cps.join(" "),
                actual(text)
            )
        })
        .collect();
    assert!(
        failures.is_empty(),
        "{name}: {} of {} cases fail:\n{}",
        failures.len(),
        cases.len(),
        failures
            .iter()
            .take(20)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
}

#[test]
fn grapheme_break_test() {
    check(
        "GraphemeBreakTest",
        include_str!("data/grapheme_break_test.txt"),
        |text| ends(graphemes(text)),
        853,
    );
}

#[test]
fn word_break_test() {
    check(
        "WordBreakTest",
        include_str!("data/word_break_test.txt"),
        |text| ends(words(text)),
        1944,
    );
}

#[test]
fn line_break_test() {
    check(
        "LineBreakTest",
        include_str!("data/line_break_test.txt"),
        |text| {
            line_breaks(text, Strictness::Strict)
                .map(|b| b.index)
                .collect()
        },
        19346,
    );
}
